import {arAdjustmentPacket,money} from './invoice-packet';
export const source=(p:ReturnType<typeof arAdjustmentPacket>)=>({manifest:p.manifest,account:{hotelId:p.account.hotelId,accountId:p.account.accountId,accountNo:p.account.accountNo},invoice:p.invoice,postings:p.postings,taxRows:p.taxRows,taxCodes:p.taxCodes,arDetails:p.arDetails});
export function currentPacket(amount=100){
 const p=arAdjustmentPacket();p.manifest.open=3315+amount;p.invoice.amount=p.invoice.balance=money(p.manifest.open);p.postings.invoicePostingsDetails[1].debitAmount=money(amount);p.arDetails[0].response.transactions[0].debitAmount=p.arDetails[0].response.transactions[0].postedAmount=money(amount);
 for(const row of p.postings.invoicePostingsDetails){const root=p.taxRows.find(r=>r.posting.transactionNo===row.transactionNo);if(root)Object.assign(root.posting,{transactionCode:row.transactionCode,transactionDate:row.transactionDate,postedAmount:money(Math.abs(row.debitAmount.amount))});}
 const code='AR-ADJUSTMENT',rules={transactionCode:{hotelId:'KAT',code,classification:{type:'Revenue',group:{code:'RM'}},trxSetup:{generatesType:'INCLUSIVE',taxInclusive:true,nonTaxable:false},generatesSetup:{addBaseAmtTo:{bucket1:true,bucket2:false,bucket3:false},generates:[{code:'VAT',rule:{percentage:{amount:7,calculatedOn:'Base',useTaxBracket:false},posting:{adjustmentType:'NoAdjustment'}},addGeneratedAmtTo:{bucket1:false,bucket2:false,bucket3:false}}]},associatedTransactionCodes:[]}},generatedRules=[{transactionCode:{hotelId:'KAT',code:'VAT',classification:{group:{code:'TAX'}},description:{defaultText:'VAT'}}}];
 const simulation={postingId:'60001',rules,rulesAfter:structuredClone(rules),generatedRules,generatedRulesAfter:structuredClone(generatedRules),calculation:{result:{totalAmount:amount,charges:[{transactionCode:code,amount,basePosting:true,sequence:0},{transactionCode:code,amount:amount/1.07,basePosting:false,sequence:0},{transactionCode:'VAT',amount:amount*7/107,basePosting:false,sequence:1}]}}};
 return {...p,arSimulations:[simulation],currentArTaxProof:{version:1 as const,sourceBefore:structuredClone(source(p)),sourceAfter:structuredClone(source(p))}};
}
